package com.elitedarkkaiser.nubialy.xposed;
import android.content.Context;import android.graphics.*;import android.view.View;import android.widget.*;
import com.elitedarkkaiser.nubialy.SurfaceStyle.Palette;
import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class IndicatorColorTest {
 public static class ModernStatusBarWifiView extends LinearLayout {ModernStatusBarWifiView(Context c){super(c);}}
 public static class ModernStatusBarMobileView extends LinearLayout {ModernStatusBarMobileView(Context c){super(c);}}
 public static class BatteryMeterView extends LinearLayout {BatteryMeterView(Context c){super(c);}}
 @Test public void categoriesTintIndependentlyAndNotificationsNeverQualify(){Context c=RuntimeEnvironment.getApplication();FrameLayout header=new FrameLayout(c);QsHeaderScope.headers.add(header);try{
  View[] views={new ModernStatusBarWifiView(c),new ModernStatusBarMobileView(c),new com.zte.mifavor.views.MFVBatteryViewLayout(c).mBatteryIconView,new com.android.systemui.statusbar.StatusBarIconView(c)};Palette p=Palette.STOCK.with(0,Color.RED).with(1,Color.GREEN).with(2,Color.BLUE).with(3,Color.MAGENTA);
  for(int i=0;i<views.length;i++){View view=views[i];if(i==2)header.addView((View)view.getParent().getParent());else header.addView(view);view.layout(0,0,40,30);assertEquals(i,IndicatorColorBackend.role(view));Bitmap bitmap=Bitmap.createBitmap(40,30,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);int before=canvas.getSaveCount();int save=IndicatorColorBackend.layer(view,canvas,p);assertTrue(save>0);canvas.drawColor(Color.WHITE);canvas.restoreToCount(save);assertEquals(before,canvas.getSaveCount());assertEquals(p.get(i),bitmap.getPixel(20,15));assertEquals(-1,IndicatorColorBackend.layer(view,canvas,Palette.STOCK));}
  var notification=new com.android.systemui.statusbar.StatusBarIconView(c);notification.notification=true;header.addView(notification);assertEquals(-1,IndicatorColorBackend.role(notification));var container=new com.android.systemui.statusbar.phone.NotificationIconContainer(c);header.addView(container);var fakeWifi=new ModernStatusBarWifiView(c);container.addView(fakeWifi);assertEquals(-1,IndicatorColorBackend.role(fakeWifi));var nested=new com.android.systemui.statusbar.StatusBarIconView(c);((LinearLayout)views[0]).addView(nested);assertEquals(-1,IndicatorColorBackend.role(nested));assertEquals(-1,IndicatorColorBackend.role(new ModernStatusBarWifiView(c)));
  var owner=(com.zte.mifavor.views.MFVBatteryViewLayout)views[2].getParent().getParent();assertEquals(-1,IndicatorColorBackend.role(owner));assertEquals(8,IndicatorColorBackend.role(owner.mBatteryLevelInsideView));assertEquals(8,IndicatorColorBackend.role(owner.mBatteryLevelOutsideView));assertEquals(2,IndicatorColorBackend.role(owner.mInsideChargeView));var unrelated=new TextView(c);owner.addView(unrelated);assertEquals(-1,IndicatorColorBackend.role(unrelated));Palette separate=p.with(8,Color.YELLOW);owner.mBatteryLevelInsideView.layout(0,0,40,30);Bitmap b=Bitmap.createBitmap(40,30,Bitmap.Config.ARGB_8888);Canvas c2=new Canvas(b);int save=IndicatorColorBackend.layer(owner.mBatteryLevelInsideView,c2,separate);c2.drawColor(Color.WHITE);c2.restoreToCount(save);assertEquals(Color.YELLOW,b.getPixel(20,15));assertEquals(Color.BLUE,separate.battery());
 }finally{QsHeaderScope.headers.clear();}}
}
